
--Lotes de la entidad, query para agrupar aprox 50k filas de error sin crash
select lot.idelote,lot.feccarga, count(dv.idedet)
 from app_iaa_interfaz.int_lote lot,
     app_iaa_interfaz.int_lotedet det,
     app_iaa_interfaz.int_lotedet_val dv
    where lot.ideentidad in ( &entidad)
    --and lot.feccarga >= to_date('01/01/2023','dd/mm/yyyy')--&fechaini--'01/01/2023'
    --and lot.feccarga <= to_date('31/01/2023','dd/mm/yyyy')--&fechafin--'01/05/2023'
    and det.idelote = lot.idelote
    and det.idptipotrama = 'D'
    and det.stsestado = 'ERR'
   and det.idedet = dv.idedet
   and det.idelote = dv.idelote
    and dv.STSESTADO=1
    --and det.idelote 
    group by lot.idelote,lot.feccarga
    order by lot.idelote;


